diff --git a/test/signup.test.ts b/test/signup.test.ts
--- /dev/null
+++ b/test/signup.test.ts
@@ -0,0 +1,81 @@
+import { test, beforeEach } from "node:test";
+import assert from "node:assert/strict";
+import { app } from "../src/api/routes.ts";
+import { authenticate, publicUser, resetUsers } from "../src/auth/users.ts";
+import { resetSessions } from "../src/auth/session.ts";
+
+const signup = (body: unknown) =>
+  app({ method: "POST", path: "/api/signup", body, headers: {} });
+
+beforeEach(() => {
+  resetUsers();
+  resetSessions();
+});
+
+test("signup registers a user and returns a working session", async () => {
+  const res = await signup({
+    email: " ADA@example.com ",
+    name: " Ada ",
+    password: "correct horse",
+  });
+  assert.equal(res.status, 201);
+  const { token, user } = res.body as {
+    token: string;
+    user: { id: string; email: string; name: string };
+  };
+  assert.equal(typeof token, "string");
+  assert.ok(token.length > 0);
+  const registered = authenticate("ada@example.com", "correct horse");
+  assert.ok(registered);
+  assert.deepEqual(user, publicUser(registered));
+  assert.deepEqual(user, {
+    id: registered.id,
+    email: "ada@example.com",
+    name: "Ada",
+  });
+  const me = await app({
+    method: "GET",
+    path: "/api/me",
+    headers: { authorization: `Bearer ${token}` },
+  });
+  assert.equal(me.status, 200);
+  assert.deepEqual(me.body, user);
+});
+
+test("signup rejects missing and non-string fields", async () => {
+  const valid = {
+    email: "ada@example.com",
+    name: "Ada",
+    password: "correct horse",
+  };
+  for (const field of ["email", "name", "password"]) {
+    for (const value of [undefined, 123]) {
+      const res = await signup({ ...valid, [field]: value });
+      assert.equal(res.status, 400);
+      assert.deepEqual(res.body, {
+        error: "email, name and password are required",
+      });
+    }
+  }
+});
+
+test("signup converts UserError to a 400 response", async () => {
+  const valid = {
+    email: "ada@example.com",
+    name: "Ada",
+    password: "correct horse",
+  };
+  for (const [body, error] of [
+    [{ ...valid, email: "invalid" }, "invalid email"],
+    [{ ...valid, password: "short" }, "password must be at least 8 characters"],
+  ] as const) {
+    const res = await signup(body);
+    assert.equal(res.status, 400);
+    assert.deepEqual(res.body, { error });
+  }
+
+  assert.equal((await signup(valid)).status, 201);
+  const duplicate = await signup({ ...valid, email: "ADA@example.com" });
+  assert.equal(duplicate.status, 400);
+  assert.deepEqual(duplicate.body, { error: "email already registered" });
+});

